// Package: Microsoft.Extensions.AI
// Install: dotnet add package Microsoft.Extensions.AI.OpenAI --version 9.*

using Microsoft.Extensions.AI;
using OpenAI;

public sealed class ProductSearchTool : AIFunction
{
    private readonly AppDbContext _db;

    public ProductSearchTool(AppDbContext db)
    {
        _db = db;
    }

    public override string Name => "search_products";
    public override string Description => "Search the product catalog by keyword and category.";

    public override async ValueTask<object?> InvokeAsync(
        ReadOnlySpan<JsonElement> arguments,
        CancellationToken cancellationToken = default)
    {
        string keyword = arguments.FirstOrDefault(a => a.NameEquals("keyword")).GetString() ?? string.Empty;
        string? category = arguments.FirstOrDefault(a => a.NameEquals("category")).GetString();

        IQueryable<Product> query = _db.Products.AsQueryable();

        if (!string.IsNullOrWhiteSpace(keyword))
            query = query.Where(p => p.Name.Contains(keyword));
        if (!string.IsNullOrWhiteSpace(category))
            query = query.Where(p => p.Category == category);

        try
        {
            return await query.ToListAsync(cancellationToken);
        }
        catch (OperationCanceledException)
        {
            // Handle graceful cancellation
            throw;
        }
        catch (Exception ex)
        {
            Console.Error.WriteLine($"Product search failed: {ex.Message}");
            throw;
        }
    }
}

// Usage example
var dbContext = new AppDbContext(connectionString);
var searchTool = new ProductSearchTool(dbContext);

// When an AI client sees this tool, it may request:
